import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const err = (m) => fail(`error: line ${n}: ${m}`)
  if (t[0] === 'candidates') {
    if (cands !== null || ballots.length) err('candidates must be declared once, before any ballot')
    if (t.length < 2) err('expected candidates <name>...')
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) err(`invalid candidate name ${name}`)
      if (seen.has(name)) err(`candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (cands === null) err('candidates must be declared once, before any ballot')
    if (t.length < 3) err('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(t[1])) err('count must be a positive integer')
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.includes(name)) err(`unknown candidate ${name}`)
      if (seen.has(name)) err(`candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
  } else err(`unknown directive ${t[0]}`)
})
if (cands === null) fail('error: no candidates')

const alive = new Set(cands)
const history = []
const out = []
let winner = null
let nrounds = 0
for (;;) {
  nrounds++
  const counts = new Map([...alive].map((c) => [c, 0]))
  let active = 0
  for (const b of ballots) {
    const c = b.prefs.find((p) => alive.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const total = ballots.reduce((s, b) => s + b.count, 0)
  const list = [...counts.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  let line = `round ${nrounds}: ` + list.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0) break
  const w = list.find(([, v]) => v * 2 > active)
  if (w) {
    winner = w[0]
    break
  }
  let tied = list.filter(([, v]) => v === list[list.length - 1][1]).map(([c]) => c)
  for (let r = 0; r < history.length && tied.length > 1; r++) {
    const vals = tied.map((c) => history[r].get(c))
    const min = Math.min(...vals)
    if (vals.some((v) => v !== min)) {
      tied = tied.filter((c) => history[r].get(c) === min)
      r = -1
    }
  }
  tied.sort()
  const el = tied[tied.length - 1]
  alive.delete(el)
  out.push(`eliminated ${el}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
process.stdout.write((mode === 'rounds' ? out.join('\n') + '\n' : `rounds ${nrounds}\n`) + end + '\n')
EOF
